"""Independent discrete-multiset,raw Hom-boundary,weight and diagnostic controls."""

ORIGINAL = 'fn original_compose(\n    name: &str,\n    p: &DeclaredFiniteRelationalProfunctor,\n    q: &DeclaredFiniteRelationalProfunctor,\n    intermediate_objects: &[&str],\n) -> Result<DeclaredFiniteRelationalProfunctor, String> {\n    if p.target_category != q.source_category {\n        return Err(format!(\n            "Cannot compose profunctors: P targets {} but Q sources {}",\n            p.target_category, q.source_category\n        ));\n    }\n\n    let mut result =\n        DeclaredFiniteRelationalProfunctor::new(name, &p.source_category, &q.target_category);\n\n    // Collect all source objects from P and target objects from Q\n    let source_objects: Vec<_> = p\n        .relations\n        .keys()\n        .map(|(a, _)| a.clone())\n        .collect::<std::collections::BTreeSet<_>>()\n        .into_iter()\n        .collect();\n\n    let target_objects: Vec<_> = q\n        .relations\n        .keys()\n        .map(|(_, c)| c.clone())\n        .collect::<std::collections::BTreeSet<_>>()\n        .into_iter()\n        .collect();\n\n    for a in &source_objects {\n        for c in &target_objects {\n            for &b in intermediate_objects {\n                let p_ab = p.hom_set(a, b);\n                let q_bc = q.hom_set(b, c);\n                for pw in p_ab {\n                    for qw in q_bc {\n                        let witness = format!("({},{})@{}", pw, qw, b);\n                        result.add_witness(a, c, &witness);\n                    }\n                }\n            }\n        }\n    }\n\n    Ok(result)\n}\nfn original_companion(\n    name: &str,\n    functor: &DeclaredFiniteFunctor,\n    target_category: &DeclaredFiniteCategory,\n) -> DeclaredFiniteRelationalProfunctor {\n    let mut prof = DeclaredFiniteRelationalProfunctor::new(\n        name,\n        &functor.source_category,\n        &functor.target_category,\n    );\n\n    for (a, fa) in &functor.object_map {\n        for morphism in target_category.morphisms.values() {\n            if morphism.source == *fa {\n                prof.add_witness(a, &morphism.target, &morphism.name);\n            }\n        }\n    }\n\n    prof\n}\nfn original_conjoint(\n    name: &str,\n    functor: &DeclaredFiniteFunctor,\n    target_category: &DeclaredFiniteCategory,\n) -> DeclaredFiniteRelationalProfunctor {\n    let mut prof = DeclaredFiniteRelationalProfunctor::new(\n        name,\n        &functor.target_category,\n        &functor.source_category,\n    );\n\n    for (a, fa) in &functor.object_map {\n        for morphism in target_category.morphisms.values() {\n            if morphism.target == *fa {\n                prof.add_witness(&morphism.source, a, &morphism.name);\n            }\n        }\n    }\n\n    prof\n}'

TESTS = r'''
#[test]fn raw_relations_preserve_metadata_order_and_queries(){
 let mut p=DeclaredFiniteRelationalProfunctor::new("λ\0","C","D");assert_eq!((&*p.name,&*p.source_category,&*p.target_category),("λ\0","C","D"));assert!(p.relations.is_empty()&&p.left_action.is_empty()&&p.right_action.is_empty());
 p.add_witness("a","x","");p.add_witness("a","x","");p.add_witness("a","y","z");assert_eq!(p.hom_set("a","x"),["",""]);assert_eq!(p.hom_set("a","y"),["z"]);assert!(p.hom_set("missing","x").is_empty());assert!(p.is_related("a","x"));assert!(!p.is_related("a","missing"));assert_eq!(p.total_witnesses(),3);assert_eq!(p.clone(),p);
}
#[test]fn all_two_by_two_multisets_discrete_middle(){
 let mut cases=0;for code in 0usize..6561{let mut n=code;let mut counts=[0usize;8];for x in &mut counts{*x=n%3;n/=3;}
  let mut p=DeclaredFiniteRelationalProfunctor::new("P","C","D");let mut q=DeclaredFiniteRelationalProfunctor::new("Q","D","E");
  for a in 0..2{for b in 0..2{p.relations.insert((format!("a{a}"),format!("b{b}")),(0..counts[a*2+b]).map(|i|format!("p{i}")).collect());q.relations.insert((format!("b{a}"),format!("c{b}")),(0..counts[4+a*2+b]).map(|i|format!("q{i}")).collect());}}
  p.left_action.insert(("unadmitted".into(),"".into(),"".into()),vec![(usize::MAX,usize::MAX)]);
  for middle in [&[][..],&[1,0][..],&[1,0,1][..]]{let names:Vec<_>=middle.iter().map(|b|if *b==0{"b0"}else{"b1"}).collect();let out=compose_relational_profunctors_discrete_middle("QP",&p,&q,&names).unwrap();let mut expected=BTreeMap::new();
   for a in 0..2{for c in 0..2{let mut values=Vec::new();for &b in middle{for i in 0..counts[a*2+b]{for j in 0..counts[4+b*2+c]{values.push(format!("(p{i},q{j})@b{b}"));}}}if !values.is_empty(){expected.insert((format!("a{a}"),format!("c{c}")),values);}}}
   assert_eq!(out.relations,expected);assert_eq!((&*out.name,&*out.source_category,&*out.target_category),("QP","C","E"));assert!(out.left_action.is_empty()&&out.right_action.is_empty());assert_eq!(out,original_compose("QP",&p,&q,&names).unwrap());cases+=1;
  }
 }assert_eq!(cases,19683);
 let p=DeclaredFiniteRelationalProfunctor::new("","C","mismatch");let q=DeclaredFiniteRelationalProfunctor::new("","D","E");assert_eq!(compose_relational_profunctors_discrete_middle("",&p,&q,&[]).unwrap_err(),"Cannot compose profunctors: P targets mismatch but Q sources D");
}
#[test]fn literal_aliases_and_raw_companion_conjoint(){
 let mut p=DeclaredFiniteRelationalProfunctor::new("","C","D");let mut q=DeclaredFiniteRelationalProfunctor::new("","D","E");p.add_witness("a","λ\0","(x,y)@z");q.add_witness("λ\0","c","");let out=compose_relational_profunctors_discrete_middle("",&p,&q,&["missing","λ\0","λ\0"]).unwrap();assert_eq!(out.hom_set("a","c"),["((x,y)@z,)@λ\0","((x,y)@z,)@λ\0"]);
 let mut category=DeclaredFiniteCategory::new("different raw name");for a in ["","X","Y"]{for b in ["","X","Y"]{let key=format!("key{a}|{b}");category.add_morphism(&key,a,b);category.morphisms.get_mut(&key).unwrap().name=format!("payload{b}|{a}");}}
 let functor=DeclaredFiniteFunctor{name:"raw".into(),source_category:"S".into(),target_category:"T".into(),object_map:BTreeMap::from([("a".into(),"X".into()),("b".into(),"X".into()),("c".into(),"".into()),("absent".into(),"missing".into())]),morphism_map:BTreeMap::new()};
 for reverse in [false,true]{let out=if reverse{declared_conjoint_profunctor("H",&functor,&category)}else{declared_companion_profunctor("H",&functor,&category)};let mut expected:BTreeMap<(String,String),Vec<String>>=BTreeMap::new();for (a,fa) in &functor.object_map{for m in category.morphisms.values(){let (boundary,key)=if reverse{(&m.target,(m.source.clone(),a.clone()))}else{(&m.source,(a.clone(),m.target.clone()))};if boundary==fa{expected.entry(key).or_default().push(m.name.clone());}}}assert_eq!(out.relations,expected);assert_eq!(out.name,"H");assert_eq!((&*out.source_category,&*out.target_category),if reverse{("T","S")}else{("S","T")});assert!(out.left_action.is_empty()&&out.right_action.is_empty());assert_eq!(out,if reverse{original_conjoint("H",&functor,&category)}else{original_companion("H",&functor,&category)});}
}
#[test]fn exact_weights_refuse_invalid_without_mutation(){
 for n in [-2,0,2,6]{for d in [-2,0,2,4]{let mut p=DeclaredFiniteWeightedProfunctor::new("W","C","D");assert_eq!((&*p.name,&*p.source_category,&*p.target_category),("W","C","D"));let before=p.weighted_relations().clone();let weight=BigRational::new_raw(n.into(),d.into());let error=format!("Weight must be finite and non-negative, got {}",weight);let result=p.add_weighted_witness("a","b","w",weight.clone());if d<=0||n<0{assert_eq!(result,Err(error));assert_eq!(p.weighted_relations(),&before);}else{assert_eq!(result,Ok(()));assert_eq!(p.weighted_relations()[&("a".into(),"b".into())],vec![("w".into(),weight)]);assert_eq!(p.total_weight("a","b"),BigRational::new(n.into(),d.into()));}assert_eq!(p.total_weight("absent","b"),BigRational::zero());}}
 let mut p=DeclaredFiniteWeightedProfunctor::new("","","");for n in [1,2,0]{p.add_weighted_witness("a","b","same",BigRational::new(n.into(),2.into())).unwrap();}assert_eq!(p.total_weight("a","b"),BigRational::new(3.into(),2.into()));assert_eq!(p.weighted_relations()[&("a".into(),"b".into())].len(),3);
}
#[test]fn boundary_reports_have_exact_scope_and_order(){
 let mut source=DeclaredFiniteCategory::new("C");source.add_object("a");let mut target=DeclaredFiniteCategory::new("D");target.add_object("b");
 for mask in 0usize..16{let mut p=DeclaredFiniteRelationalProfunctor::new("P",if mask&1==0{"C"}else{"badC"},if mask&2==0{"D"}else{"badD"});let a=if mask&4==0{"a"}else{"missingA"};let b=if mask&8==0{"b"}else{"missingB"};p.relations.insert((a.into(),b.into()),Vec::new());p.left_action.insert(("bogus".into(),"".into(),"".into()),vec![(usize::MAX,usize::MAX)]);let report=validate_relational_profunctor(&p,&source,&target);assert_eq!(report.target_name,"P");let mut expected=Vec::new();if mask&1!=0{expected.push((ValidationLocation::Global,"Source category mismatch: expected C, got badC".to_owned()));}if mask&2!=0{expected.push((ValidationLocation::Global,"Target category mismatch: expected D, got badD".to_owned()));}if mask&4!=0{expected.push((ValidationLocation::Object("missingA".into()),"Source object missingA not in source category C".to_owned()));}if mask&8!=0{expected.push((ValidationLocation::Object("missingB".into()),"Target object missingB not in target category D".to_owned()));}assert_eq!(report.typed_violations.len(),expected.len());for (actual,(location,message)) in report.typed_violations.iter().zip(expected){assert_eq!(actual.unit,ValidationUnit::Other("ProfunctorBoundary".into()));assert_eq!(actual.location,location);assert_eq!(actual.message,message);assert_eq!(actual.severity,ValidationSeverity::Error);}}
}
'''


def challenge(subject):
    return '\n#[cfg(test)]mod independent_profunctor_tests{use super::*;\n'+ORIGINAL+TESTS+'\n}\n'
